-- GERADO por importers/run.py (rodovias_estaduais/der-mg). Fonte: https://observatorio.infraestrutura.mg.gov.br/server/rest/services/00_PUBLICACOES/pontos_criticos_publico/FeatureServer/0. Licença: Não declarada: o item do Observatório da Infraestrutura (SEINFRA-MG/DER-MG) tem licenseInfo vazio. O site do DER-MG ("Aspectos legais") permite reutilizar conteúdo "desde que identificada a fonte e atribuído o crédito". RISCO: uso comercial sem autorização expressa (pedir termo ao DER-MG/SEINFRA ou via LAI; ver docs/layers/rodovias_estaduais.md). Não edite à mão.
-- Fonte viva: o seed não traz feições (elas venceriam em 72 h e sobrescreveriam dados frescos a cada migrate).
delete from data_features where layer_id = $q$rodovias_estaduais$q$ and source = $q$der-mg$q$ and valid_to is not null and valid_to < now();
insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes)
select $q$rodovias_estaduais$q$, $q$der-mg$q$, $q$https://observatorio.infraestrutura.mg.gov.br/server/rest/services/00_PUBLICACOES/pontos_criticos_publico/FeatureServer/0$q$, $q$Não declarada: o item do Observatório da Infraestrutura (SEINFRA-MG/DER-MG) tem licenseInfo vazio. O site do DER-MG ("Aspectos legais") permite reutilizar conteúdo "desde que identificada a fonte e atribuído o crédito". RISCO: uso comercial sem autorização expressa (pedir termo ao DER-MG/SEINFRA ou via LAI; ver docs/layers/rodovias_estaduais.md)$q$, 0, $q$seed sem feições: fonte viva (pontos críticos do DER-MG). Rode o importador rodovias_estaduais_der_mg de hora em hora ou ao menos 1×/dia; cada carga vale 72 h (valid_to).$q$
 where not exists (select 1 from data_layer_runs where layer_id = $q$rodovias_estaduais$q$ and source = $q$der-mg$q$);
